window.AUTH=window.AUTH||{};window.AUTH["23-713"]={"d":"23-713","id":"2024/23-713","n":"Bufkin v. McDonough","briefs":[{"k":"petitioner","label":"Brief of petitioners Joshua E. Bufkin, et al.","date":"2024-07-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-713/316195/20240702124612575_Bufkin%20Merits%20Opening%20Brief.pdf","side":"pet","n":73},{"k":"respondent","label":"Brief of respondent Denis McDonough, Secretary of Veterans Affairs","date":"2024-08-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-713/322988/20240820175858007_23-713bs_Bufkin_final.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioners Joshua E. Bufkin, et al.","date":"2024-09-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-713/326344/20240919131037085_Bufkin%20Merits%20Reply.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r17_olp1.pdf","tr":true,"items":[{"t":"case","label":"Abbott v. Perez","cite":"585 U.S. 579","y":2018,"id":"2017/17-586","sc":1,"sum":"The Court decided that the district court erred in disregarding the presumption of good faith on the part of the Texas Legislature and improperly reversed the burden of proof in requiring the state to show a lack of discriminatory intent in adopting new districting plans; the Court also held that one of the state house districts at issue was an impermissible racial gerrymander.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Affum v. United States","cite":"566 F.3d 1150","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/566/1150/","by":{"0":"48"}},{"t":"case","label":"Anderson v. City of Bessemer City","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"op":2,"ar":2,"sum":"The Court of Appeals misapprehended and misapplied the clearlyerroneous standard and accordingly erred in denying petitioner relief under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"23, 24","2":"23"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"op":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"0":"37","1":"37"}},{"t":"case","label":"Burris v. Wilkie","cite":"888 F.3d 1352","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/888/1352/","by":{"0":"25"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"op":3,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"0":"30, 31"}},{"t":"case","label":"Francway v. Wilkie","cite":"940 F.3d 1304","y":2019,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/940/1304/","by":{"0":"46"}},{"t":"case","label":"Gilbert v. Derwinski","cite":"1 Vet. App. 49","y":1990,"url":"https://www.courtlistener.com/c/Vet.%20App./1/49/","op":2,"ar":2,"by":{"0":"7, 25","2":"6, 8, 20"}},{"t":"case","label":"Heckler v. Day","cite":"467 U.S. 104","y":1984,"id":"1983/82-1371","sc":1,"sum":"In a 5-to-4 opinion, the Court held that Congress already considered and expressly rejected the imposition of mandatory disability dispute-resolution deadlines. Such deadlines, according to congressional reports, would subordinate quality of service to timeliness.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":4,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"8, 24, 25, 26, 37, 50","1":"19, 24, 33, 36"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"42, 51"}},{"t":"case","label":"Husky Int’l Elecs., Inc. v. Ritz","cite":"578 U.S. 355","y":2016,"id":"2015/15-145","sc":1,"op":1,"sum":"The Court determined that the “actual fraud” language of the bankruptcy statute encompasses traditional forms of fraud and is not limited to fraudulent representation.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Inhabitants of Montclair Twp. v. Ramsdell","cite":"107 U.S. 147","y":1883,"id":"scdb/1882-132","sc":1,"sum":"The judgment below was in accordance with the verdict in an action brought by the defendant in error on certain bonds, payable to Samuel Holmes or bearer, and on coupons thereof payable to the holder, all dated March 17, 1870, and alleged to have been issued by the township of Montclair, Essex County, New Jersey. They are negotiable in form, and purport to have been executed in pursuance of an act approved April 9, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Interstate Com. Comm’n v. Louisville & Nashville R.R. Co.","cite":"227 U.S. 88","y":1913,"id":"scdb/1912-073","sc":1,"sum":"The Act to Regulate Commerce, as amended by the Hepburn Act, gives a right to a full hearing on the subject of rates, and that confers the privilege of introducing testimony and imposes the duty of deciding in accordance with the facets proved.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Inwood Lab’ys, Inc. v. Ives Lab’ys, Inc.","cite":"456 U.S. 844","y":1982,"id":"1981/80-2182","sc":1,"sum":"The Court of Appeals erred in setting aside the District Court's findings of fact.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"23"}},{"t":"case","label":"Jackson v. Virginia","cite":"443 U.S. 307","y":1979,"id":"1978/78-5283","sc":1,"op":2,"sum":"Petitioner was convicted of first-degree murder after a bench trial in a Virginia court, and his motion and petition in the state courts to set aside the conviction on the ground that there was insufficient evidence of premeditation, a necessary element of first-degree murder, were denied. He then brought a habeas corpus proceeding in Federal District Court, which, applying the \"no evidence\" criterion of Thompson v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Kappos v. Hyatt","cite":"566 U.S. 431","y":2012,"id":"2011/10-1219","sc":1,"sum":"The Court held that a patent applicant's ability to introduce new evidence in a civil action against the Patent and Trademark Office was only limited by the Federal Rules of Evidence and the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"op":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"0":"29","2":"7"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"sum":"The Court held that a district court conducting pretrial proceedings pursuant to section 1407(a) has no authority to invoke section 1404(a) to assign a transferred case to itself for trial.","sumSrc":"Oyez","by":{"0":"29, 30"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. __","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","2":"17"}},{"t":"case","label":"Lynch v. McDonough","cite":"21 F.4th 776","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/21/776/","by":{"0":"7, 32, 45","1":"44","2":"20"}},{"t":"case","label":"Matal v. Tam","cite":"582 U.S. 218","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"op":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"op":1,"by":{"0":"39"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Pub. Lands Council v. Babbitt","cite":"529 U.S. 728","y":2000,"id":"1999/98-1991","sc":1,"sum":"The Court held that \"[t]he regulatory changes do not exceed the Secretary's Taylor Grazing Act authority.\" \"Congress itself has directed development of land-use plans, and their use in the allocation process in order to preserve, improve and develop the public rangelands,\" wrote Justice Stephen G. Breyer. \"And the secretary [of the Interior] has always had the statutory authority...to reclassify and withdraw range land from grazing use.\".","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Reeves v. Sanderson Plumbing Prods., Inc.","cite":"530 U.S. 133","y":2000,"id":"1999/99-536","sc":1,"op":2,"ar":1,"sum":"Explaining that the suffciency-of-the-evidence inquiry is a legal question determined by the court.","sumSrc":"opinion","by":{"0":"44"}},{"t":"case","label":"Reno v. Bossier Par. Sch. Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"sum":"The Court held that section 5 does not prohibit preclearance of a redistricting plan enacted with a discriminatory but nonretrogressive purpose. \"As we have repeatedly noted, in vote-dilution cases [section 5] prevents nothing but backsliding, and preclearance under [section 5] affirms nothing but the absence of backsliding,\" wrote Justice Scalia.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Rudisill v. McDonough","cite":"601 U.S. 294","y":2024,"id":"2023/22-888","sc":1,"sum":"Servicemembers who, through separate periods of service, accrue educational benefits under both the Montgomery and Post-9/11 GI Bills may use either one, in any order, up to 38 U. S. C. §3695(a)’s 48-month aggregate-benefits cap.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37, 42","1":"37"}},{"t":"case","label":"Sanchez-Benitez v. Principi","cite":"259 F.3d 1356","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/259/1356/","by":{"0":"46"}},{"t":"case","label":"Saunders v. Wilkie","cite":"886 F.3d 1356","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/886/1356/","by":{"0":"46"}},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"op":6,"sum":"The Court found that the lower court's framework for evaluating VA (Veterans' Affairs) notice errors conflicted with the established law that the Veterans Court \"take due account of the rule of the prejudicial error.\"","sumSrc":"Oyez","by":{"0":"2, 9, 26, 28, 31, 41","1":"5, 20, 34, 35, 37","2":"6"}},{"t":"case","label":"Stewart v. Sonneborn","cite":"98 U.S. 187","y":1878,"id":"scdb/1878-067","sc":1,"sum":"This was an action brought by Meyer Sonneborn, the plaintiff below, against A. T. Stewart & Co., to recover damages for an alleged wrongful and malicious institution of proceedings in bankruptcy against him. The record shows that in the years 1865 and 1866 Sonneborn was a member of the firm of E. Leipzeiger & Co., in New York, and that while he was thus a member the firm bought goods on credit from A. T. Stewart & …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Sugrue v. Derwinski","cite":"26 F.3d 8","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/26/8/","by":{"0":"7"}},{"t":"case","label":"Tadlock v. McDonough","cite":"5 F.4th 1327","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/5/1327/","ar":3,"by":{"0":"29, 51","2":"7, 8"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"United States v. 1407 N. Collins St.","cite":"901 F.3d 268","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/901/268/","by":{"0":"44"}},{"t":"case","label":"United States v. Haggar Apparel Co.","cite":"526 U.S. 380","y":1999,"id":"1998/97-2044","sc":1,"sum":"The Court concluded that the regulation in question was subject to further analysis. Additionally, the Court held that if the regulation was a reasonable interpretation of an ambiguous statutory provision, then it required judicial deference in the Court of International Trade.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"United States v. Oregon","cite":"366 U.S. 643","y":1961,"id":"1960/329","sc":1,"sum":"The United States was entitled 'to the property as such trustee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"United States v. Quality Stores, Inc.","cite":"572 U.S. 141","y":2014,"id":"2013/12-1408","sc":1,"op":1,"sum":"The Court found that severance payments made to employees who were unwillingly laid off are taxable under the Federal Insurance Contributions Act.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Singer Mfg. Co.","cite":"374 U.S. 174","y":1963,"id":"1962/438","sc":1,"sum":"On this record, there was a conspiracy to exclude Japanese competitors, in violation of § 1 of the Sherman Act, and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Walters v. Nat’l Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"op":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 50"}},{"t":"case","label":"Weisgram v. Marley Co.","cite":"528 U.S. 440","y":2000,"id":"1999/99-161","sc":1,"ar":1,"sum":"The Court held that Federal Rule of Civil Procedure 50 permits an appellate court to direct the entry of judgment as a matter of law when it determines that evidence was erroneously admitted at trial and that the remaining, properly admitted, evidence is insufficient to constitute a submissible case.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(E)","(2)(F)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"9, 31, 41, 47, 47","1":"19, 20, 35, 20, 20"}},{"t":"usc","label":"7 U.S.C. § 2023","url":"https://www.law.cornell.edu/uscode/text/7/2023","subs":["(a)(15)"],"by":{"0":"48"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"usc","label":"35 U.S.C. § 145","url":"https://www.law.cornell.edu/uscode/text/35/145","by":{"0":"48"}},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","stext":{"head":"§1110. Basic entitlement","paras":[[0,"For disability resulting from personal injury suffered or disease contracted in line of duty, or for aggravation of a preexisting injury suffered or disease contracted in line of duty, in the active military, naval, air, or space service, during a period of war, the United States will pay to any veteran thus disabled and who was discharged or released under conditions other than dishonorable from the period of service in which said injury or disease was incurred, or preexisting injury or disease was aggravated, compensation as provided in this subchapter, but no compensation shall be paid if the disability is a result of the veteran's own willful misconduct or abuse of alcohol or drugs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1110?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1110. Basic entitlement","tname":"Veterans' Benefits","by":{"0":"46","1":"3"}},{"t":"usc","label":"38 U.S.C. § 5103","url":"https://www.law.cornell.edu/uscode/text/38/5103","subs":["(a)"],"stext":{"head":"§5103. Notice to claimants of required information and evidence","paras":[[0,"(a) Required Information and Evidence.—(1) Except as provided in paragraph (3), the Secretary shall provide to the claimant and the claimant's representative, if any, by the most effective means available, including electronic communication or notification in writing, notice of any information, and any medical or lay evidence, not previously provided to the Secretary that is necessary to substantiate the claim. As part of that notice, the Secretary shall indicate which portion of that information and evidence, if any, is to be provided by the claimant and which portion, if any, the Secretary, in accordance with section 5103A of this title and any other applicable provisions of law, will attempt to obtain on behalf of the claimant."],[0,"(2)(A) The Secretary shall prescribe in regulations requirements relating to the contents of notice to be provided under this subsection."],[0,"(B) The regulations required by this paragraph—"],[1,"(i) shall specify different contents for notice based on whether the claim concerned is an original claim or a supplemental claim;"],[1,"(ii) shall provide that the contents for such notice be appropriate to the type of benefits or services sought under the claim;"],[1,"(iii) shall specify for each type of claim for benefits the general information and evidence required to substantiate the basic elements of such type of claim; and"],[1,"(iv) shall specify the time period limitations required pursuant to subsection (b)."],[0,"(3) The requirement to provide notice under paragraph (1) shall not apply with respect to a supplemental claim that is filed within the timeframe set forth in subparagraphs (B) and (D) of section 5110(a)(2) of this title."],[0,"(b) Time Limitation.—(1) In the case of information or evidence that the claimant is notified under subsection (a) is to be provided by the claimant, such information or evidence must be received by the Secretary within one year from the date such notice is sent."],[0,"(2) This subsection shall not apply to any application or claim for Government life insurance benefits."],[0,"(3) Nothing in paragraph (1) shall be construed to prohibit the Secretary from making a decision on a claim before the expiration of the period referred to in that subsection."],[0,"(4) Nothing in this section shall require the Secretary to provide notice for a subsequent claim that is filed while a previous claim is pending if the notice previously provided for such pending claim—"],[1,"(A) provides sufficient notice of the information and evidence necessary to substantiate such subsequent claim; and"],[1,"(B) was sent within one year of the date on which the subsequent claim was filed."],[0,"(5)(A) This section shall not apply to any claim or issue where the Secretary may award the maximum benefit in accordance with this title based on the evidence of record."],[0,"(B) For purposes of this paragraph, the term \"maximum benefit\" means the highest evaluation assignable in accordance with the evidence of record, as long as such evidence is adequate for rating purposes and sufficient to grant the earliest possible effective date in accordance with section 5110 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5103?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5103. Notice to claimants of required information and evidence","tname":"Veterans' Benefits","by":{"0":"24"}},{"t":"usc","label":"38 U.S.C. § 5107","url":"https://www.law.cornell.edu/uscode/text/38/5107","subs":["(b)","(a)"],"stext":{"head":"§5107. Claimant responsibility; benefit of the doubt","paras":[[0,"(a) Claimant Responsibility.—Except as otherwise provided by law, a claimant has the responsibility to present and support a claim for benefits under laws administered by the Secretary."],[0,"(b) Benefit of the Doubt.—The Secretary shall consider all information and lay and medical evidence of record in a case before the Secretary with respect to benefits under laws administered by the Secretary. When there is an approximate balance of positive and negative evidence regarding any issue material to the determination of a matter, the Secretary shall give the benefit of the doubt to the claimant."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5107?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§5107. Claimant responsibility; benefit of the doubt","tname":"Veterans' Benefits","by":{"0":"1-7, 9-10, 13, 17, 19-24, 27-30","1":"2, 2, 4, 2, 4, 5, 14-18, 20-22, 25-27, 29, 30, 32, 36, 38-40, 42-44","2":"1-9, 11, 13-15, 17-20, 23-25"}},{"t":"usc","label":"38 U.S.C. § 7251","url":"https://www.law.cornell.edu/uscode/text/38/7251","stext":{"head":"§7251. Status","paras":[[0,"There is hereby established, under Article I of the Constitution of the United States, a court of record to be known as the United States Court of Appeals for Veterans Claims."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7251?type=usc&year=mostrecent&link-type=html"},"head":"§7251. Status","tname":"Veterans' Benefits","by":{"0":"25","1":"5"}},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","subs":["(b)","(a)"],"stext":{"head":"§7252. Jurisdiction; finality of decisions","paras":[[0,"(a) The Court of Appeals for Veterans Claims shall have exclusive jurisdiction to review decisions of the Board of Veterans' Appeals. The Secretary may not seek review of any such decision. The Court shall have power to affirm, modify, or reverse a decision of the Board or to remand the matter, as appropriate."],[0,"(b) Review in the Court shall be on the record of proceedings before the Secretary and the Board. The extent of the review shall be limited to the scope provided in section 7261 of this title. The Court may not review the schedule of ratings for disabilities adopted under section 1155 of this title or any action of the Secretary in adopting or revising that schedule."],[0,"(c) Decisions by the Court are subject to review as provided in section 7292 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7252?type=usc&year=mostrecent&link-type=html"},"head":"§7252. Jurisdiction; finality of decisions","tname":"Veterans' Benefits","by":{"0":"5, 48","1":"5, 27, 5, 19"}},{"t":"usc","label":"38 U.S.C. § 7261","url":"https://www.law.cornell.edu/uscode/text/38/7261","subs":["(a)","(a)(3)","(a)(4)","(b)","(b)(1)","(b)(2)","(c)","(d)","(a)(1)","(a)(2)","(a)(3)(A)","(a)(3)(B)","(b)(2000)"],"stext":{"head":"§7261. Scope of review","paras":[[0,"(a) In any action brought under this chapter, the Court of Appeals for Veterans Claims, to the extent necessary to its decision and when presented, shall—"],[1,"(1) decide all relevant questions of law, interpret constitutional, statutory, and regulatory provisions, and determine the meaning or applicability of the terms of an action of the Secretary;"],[1,"(2) compel action of the Secretary unlawfully withheld or unreasonably delayed;"],[1,"(3) hold unlawful and set aside decisions, findings (other than those described in clause (4) of this subsection), conclusions, rules, and regulations issued or adopted by the Secretary, the Board of Veterans' Appeals, or the Chairman of the Board found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[2,"(D) without observance of procedure required by law; and"],[1,"(4) in the case of a finding of material fact adverse to the claimant made in reaching a decision in a case before the Department with respect to benefits under laws administered by the Secretary, hold unlawful and set aside or reverse such finding if the finding is clearly erroneous."],[0,"(b) In making the determinations under subsection (a), the Court shall review the record of proceedings before the Secretary and the Board of Veterans' Appeals pursuant to section 7252(b) of this title and shall—"],[1,"(1) take due account of the Secretary's application of section 5107(b) of this title; and"],[1,"(2) take due account of the rule of prejudicial error."],[0,"(c) In no event shall findings of fact made by the Secretary or the Board of Veterans' Appeals be subject to trial de novo by the Court."],[0,"(d) When a final decision of the Board of Veterans' Appeals is adverse to a party and the sole stated basis for such decision is the failure of the party to comply with any applicable regulation prescribed by the Secretary, the Court shall review only questions raised as to compliance with and the validity of the regulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7261?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§7261. Scope of review","tname":"Veterans' Benefits","by":{"0":"2-3, 6, 19, 21-28, 33, 37-41, 3, 5, 9, 19-21, 26-29, 32-34, 36-37, 41, 48-51, 50, 10, 18-19, 21, 38-40, 48, 53, 5, 11, 26, 27, 29, 30, 49, 50, 1-4, 10, 18-23, 10, 20, 22, 28-29, 31, 35, 38, 41, 51, 27, 47, 48, 49, 27","1":"2, 5, 16, 19, 20, 22, 27, 31, 40, 2, 6, 9, 10, 14-20, 22, 24, 26, 29, 31, 35-41, 6, 19, 27, 39, 42, 19, 19, 39, 39, 2, 6, 14, 17, 19, 20, 22-24, 27, 28, 31, 32, 34, 36, 40, 42, 43, 29, 3, 6, 14, 18, 19, 21, 28, 32, 3, 14-18, 20, 21, 26-28, 30-37, 40, 42, 3, 15, 20, 34-36, 3, 6, 17, 20, 28, 34, 20","2":"1, 2, 8, 14, 16, 17, 1-7, 9-15, 18, 19, 13, 13, 18, 1, 2, 3, 7, 9, 10, 14, 1-5, 7-19, 23, 25, 3, 6-10, 14, 23"}},{"t":"law","label":"Pub. L. No. 107-330","url":"https://www.govinfo.gov/link/plaw/107/public/330","by":{"0":"10","1":"20"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"0":"8, 9","1":"5"}},{"t":"reg","label":"38 C.F.R. § 3.102","url":"https://www.ecfr.gov/current/title-38/section-3.102","by":{"0":"6, 7"}},{"t":"reg","label":"38 C.F.R. § 3.159","url":"https://www.ecfr.gov/current/title-38/section-3.159","subs":["(a)(1)"],"by":{"0":"46"}},{"t":"reg","label":"38 C.F.R. § 20.103","url":"https://www.ecfr.gov/current/title-38/section-20.103","by":{"0":"9"}},{"t":"reg","label":"50 Fed. Reg. 34452","url":"https://www.govinfo.gov/link/fr/50/34452","by":{"0":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 50","url":"https://www.law.cornell.edu/rules/frcp/rule_50","subs":["(a)"],"by":{"0":"44"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31","2":"17"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Corner Post, Inc. v. Board of Governors","cite":"144 S. Ct. 2440","y":2024,"id":"2023/22-1008","sc":1,"sum":"An Administrative Procedures Act claim does not accrue for purposes of 28 U. S. C. §2401(a)—the default 6-year statute of limitations applicable to suits against the United States—until the plaintiff is injured by final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"op":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36"}},{"t":"case","label":"Harrow v. Department of Defense","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"sum":"Title 5 U. S. C. §7703(b)(1)’s 60-day filing deadline for a federal employee to petition the Federal Circuit to review a final decision of the Merit Systems Protection Board is not jurisdictional.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Kawashima v. Holder","cite":"565 U.S. 478","y":2012,"id":"2011/10-577","sc":1,"ar":1,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"1":"30","2":"16"}},{"t":"case","label":"King v. St. Vincent’s Hospital","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"op":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Luna Perez v. Sturgis Public Schools","cite":"598 U.S. 142","y":2023,"id":"2022/21-887","sc":1,"sum":"An Americans with Disabilities Act lawsuit seeking compensatory damages for the denial of a free and appropriate education may proceed without exhausting the administrative processes of the Individuals with Disabilities Education Act, 20 U. S. C. §1415(l), because the remedy sought is not one IDEA provides.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"case","label":"Mattox v. McDonough","cite":"34 Vet. App. 61","y":2021,"url":"https://www.courtlistener.com/c/Vet.%20App./34/61/","by":{"1":"9"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"1":"30","2":"15"}},{"t":"case","label":"Ohio v. EPA","cite":"144 S. Ct. 2040","y":2024,"url":"https://www.courtlistener.com/c/S.%20Ct./144/2040/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"39","2":"12"}},{"t":"case","label":"Red Lion Broadcasting Co. v. FCC","cite":"395 U.S. 367","y":1969,"id":"1968/2","sc":1,"sum":"The Court held that the fairness doctrine was consistent with the First Amendment.","sumSrc":"Oyez","by":{"1":"33","2":"18"}},{"t":"case","label":"Roane v. McDonough","cite":"64 F.4th 1306","y":2023,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/64/1306/","by":{"1":"10, 40-42","2":"14"}},{"t":"case","label":"Schaffer v. Weast","cite":"546 U.S. 49","y":2005,"id":"2005/04-698","sc":1,"sum":"In a 6 to 2 ruling, the Supreme Court held that the party bringing the suit bears the burden of proof, whether that party is the parents or the school system. In the majority opinion, Justice Sandra Day O'Connor wrote that \"absent some reason to believe that Congress intended otherwise, ... we will conclude that the burden of persuasion lies where it usually falls, upon the party seeking relief.\".","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Scheidler v. National Organization for Women, Inc.","cite":"547 U.S. 9","y":2006,"id":"2005/04-1244","sc":1,"sum":"The Court ruled that \"physical violence unrelated to robbery or extortion falls outside the scope of the Hobbs Act.\" Writing for the unanimous Court, Justice Stephen Breyer cited statutory language, legislative history, and case law in support of the decision.","sumSrc":"Oyez","by":{"1":"29","2":"16"}},{"t":"case","label":"Shapiro v. McManus","cite":"577 U.S. 39","y":2015,"id":"2015/14-990","sc":1,"op":1,"sum":"The Court held that a claim covered by the Three-Judge Court Act must be heard by a three-judge panel.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Teva Pharmaceuticals USA, Inc. v. Sandoz, Inc.","cite":"574 U.S. 318","y":2015,"id":"2014/13-854","sc":1,"sum":"The Court ruled that a federal appellate court can only overturn a district court’s finding of fact if those findings were determined to be “clearly erroneous.”","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42"}},{"t":"case","label":"U.S. Bank N.A. v. Village at Lakeridge, LLC","cite":"583 U.S. 387","y":2018,"id":"2017/15-1509","sc":1,"op":7,"sum":"The Court held that a designation of non-statutory insider status is reviewable under the standard of clear error because the \"mixed question\" of law and fact at issue is primarily factual.","sumSrc":"Oyez","by":{"1":"23, 25, 28","2":"21"}},{"t":"case","label":"United States v. Rahimi","cite":"144 S. Ct. 1889","y":2024,"id":"2023/22-915","sc":1,"sum":"When an individual has been found by a court to pose a credible threat to the physical safety of another, that individual may be temporarily disarmed consistent with the Second Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21"}},{"t":"case","label":"WildEarth Guardians v. United States Bureau of Land Management","cite":"870 F.3d 1222","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/870/1222/","by":{"1":"35"}},{"t":"case","label":"Wilkinson v. Garland","cite":"601 U.S. 209","y":2024,"id":"2023/22-666","sc":1,"op":1,"sum":"The Immigration Judge’s discretionary decision that Mr. Wilkinson failed to satisfy 8 U. S. C. §1229b(b)(1)(D)’s “exceptional and extremely unusual” hardship standard for determining eligibility for cancellation of removal is a mixed question of law and fact, reviewable under §1252(a)(2)(D)’s jurisdiction restoring exception for “questions of law”; the Third Circuit’s holding that the IJ’s decision was unreviewable under §1252(a)(2)(B)(i) was in error.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25","2":"21"}},{"t":"case","label":"Wittman v. Personhuballah","cite":"578 U.S. 539","y":2016,"id":"2015/14-1504","sc":1,"sum":"The Court determined that members of Congress whose chances of reelection might be impaired by a new districting plan did not have standing under Article III of the U.S. Constitution to appeal their case to the Supreme Court.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Zenith Radio Corp. v. Hazeltine Research, Inc.","cite":"395 U.S. 100","y":1969,"id":"1968/49","sc":1,"sum":"Upon the expiration in 1959 of petitioner, Zenith's, license agreement with Hazeltine Research, Inc. (HRI), which permitted Zenith to use all of HRI's domestic radio and television patents under HRI's so-called standard package license, Zenith refused to renew, asserting that it no longer required a license. HRI brought a patent infringement suit in November 1959. Zenith's answer alleged invalidity of the patent, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"19, 20, 35"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","by":{"1":"35"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(d)(8)"],"by":{"1":"35"}},{"t":"usc","label":"38 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/38/101","subs":["(16)"],"by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/38/501","subs":["(a)(1)"],"by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/38/511","subs":["(a)"],"by":{"1":"5"}},{"t":"usc","label":"38 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/38/1131","by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 1155","url":"https://www.law.cornell.edu/uscode/text/38/1155","stext":{"head":"§1155. Authority for schedule for rating disabilities","paras":[[0,"The Secretary shall adopt and apply a schedule of ratings of reductions in earning capacity from specific injuries or combination of injuries. The ratings shall be based, as far as practicable, upon the average impairments of earning capacity resulting from such injuries in civil occupations. The schedule shall be constructed so as to provide ten grades of disability and no more, upon which payments of compensation shall be based, namely, 10 percent, 20 percent, 30 percent, 40 percent, 50 percent, 60 percent, 70 percent, 80 percent, 90 percent, and total, 100 percent. The Secretary shall from time to time readjust this schedule of ratings in accordance with experience. However, in no event shall such a readjustment in the rating schedule cause a veteran's disability rating in effect on the effective date of the readjustment to be reduced unless an improvement in the veteran's disability is shown to have occurred."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1155?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1155. Authority for schedule for rating disabilities","tname":"Veterans' Benefits","by":{"1":"4"}},{"t":"usc","label":"38 U.S.C. § 5103A","url":"https://www.law.cornell.edu/uscode/text/38/5103A","subs":["(a)(1)"],"stext":{"head":"§5103A. Duty to assist claimants","paras":[[0,"(a) Duty To Assist.—(1) The Secretary shall make reasonable efforts to assist a claimant in obtaining evidence necessary to substantiate the claimant's claim for a benefit under a law administered by the Secretary."],[0,"(2) The Secretary is not required to provide assistance to a claimant under this section if no reasonable possibility exists that such assistance would aid in substantiating the claim."],[0,"(3) The Secretary may defer providing assistance under this section pending the submission by the claimant of essential information missing from the claimant's application."],[0,"(b) Assistance in Obtaining Private Records.—(1) As part of the assistance provided under subsection (a), the Secretary shall make reasonable efforts to obtain relevant private records that the claimant adequately identifies to the Secretary."],[0,"(2)(A) Whenever the Secretary, after making such reasonable efforts, is unable to obtain all of the relevant records sought, the Secretary shall notify the claimant that the Secretary is unable to obtain records with respect to the claim. Such a notification shall—"],[1,"(i) identify the records the Secretary is unable to obtain;"],[1,"(ii) briefly explain the efforts that the Secretary made to obtain such records; and"],[1,"(iii) explain that the Secretary will decide the claim based on the evidence of record but that this section does not prohibit the submission of records at a later date if such submission is otherwise allowed."],[0,"(B) The Secretary shall make not less than two requests to a custodian of a private record in order for an effort to obtain relevant private records to be treated as reasonable under this section, unless it is made evident by the first request that a second request would be futile in obtaining such records."],[0,"(3)(A) This section shall not apply if the evidence of record allows for the Secretary to award the maximum benefit in accordance with this title based on the evidence of record."],[0,"(B) For purposes of this paragraph, the term \"maximum benefit\" means the highest evaluation assignable in accordance with the evidence of record, as long as such evidence is adequate for rating purposes and sufficient to grant the earliest possible effective date in accordance with section 5110 of this title."],[0,"(4) Under regulations prescribed by the Secretary, the Secretary—"],[1,"(A) shall encourage claimants to submit relevant private medical records of the claimant to the Secretary if such submission does not burden the claimant; and"],[1,"(B) in obtaining relevant private records under paragraph (1), may require the claimant to authorize the Secretary to obtain such records if such authorization is required to comply with Federal, State, or local law."],[0,"(c) Obtaining Records for Compensation Claims.—(1) In the case of a claim for disability compensation, the assistance provided by the Secretary under this section shall include obtaining the following records if relevant to the claim:"],[1,"(A) The claimant's service medical records and, if the claimant has furnished the Secretary information sufficient to locate such records, other relevant records pertaining to the claimant's active military, naval, air, or space service that are held or maintained by a governmental entity."],[1,"(B) Records of relevant medical treatment or examination of the claimant at Department health-care facilities or at the expense of the Department, if the claimant furnishes information sufficient to locate those records."],[1,"(C) Any other relevant records held by any Federal department or agency that the claimant adequately identifies and authorizes the Secretary to obtain."],[0,"(2) Whenever the Secretary attempts to obtain records from a Federal department or agency under this subsection, the efforts to obtain those records shall continue until the records are obtained unless it is reasonably certain that such records do not exist or that further efforts to obtain those records would be futile."],[0,"(d) Medical Examinations for Compensation Claims.—(1) In the case of a claim for disability compensation, the assistance provided by the Secretary under subsection (a) shall include providing a medical examination or obtaining a medical opinion when such an examination or opinion is necessary to make a decision on the claim."],[0,"(2) The Secretary shall treat an examination or opinion as being necessary to make a decision on a claim for purposes of paragraph (1) if the evidence of record before the Secretary, taking into consideration all information and lay or medical evidence (including statements of the claimant)—"],[1,"(A) contains competent evidence that the claimant has a current disability, or persistent or recurrent symptoms of disability; and"],[1,"(B) indicates that the disability or symptoms may be associated with the claimant's active military, naval, air, or space service; but"],[1,"(C) does not contain sufficient medical evidence for the Secretary to make a decision on the claim."],[0,"(e) Applicability of Duty to Assist.—(1) The Secretary's duty to assist under this section shall apply only to a claim, or supplemental claim, for a benefit under a law administered by the Secretary until the time that a claimant is provided notice of the agency of original jurisdiction's decision with respect to such claim, or supplemental claim, under section 5104 of this title."],[0,"(2) The Secretary's duty to assist under this section shall not apply to higher-level review by the agency of original jurisdiction, pursuant to section 5104B of this title, or to review on appeal by the Board of Veterans' Appeals."],[0,"(f) Correction of Duty to Assist Errors.—(1) If, during review of the agency of original jurisdiction decision under section 5104B of this title, the higher-level adjudicator identifies or learns of an error on the part of the agency of original jurisdiction to satisfy its duties under this section, and that error occurred prior to the agency of original jurisdiction decision being reviewed, unless the Secretary may award the maximum benefit in accordance with this title based on the evidence of record, the higher-level adjudicator shall return the claim for correction of such error and readjudication."],[0,"(2)(A) If the Board of Veterans' Appeals, during review on appeal of an agency of original jurisdiction decision, identifies or learns of an error on the part of the agency of original jurisdiction to satisfy its duties under this section, and that error occurred prior to the agency of original jurisdiction decision on appeal, unless the Secretary may award the maximum benefit in accordance with this title based on the evidence of record, the Board shall remand the claim to the agency of original jurisdiction for correction of such error and readjudication."],[0,"(B) Remand for correction of such error may include directing the agency of original jurisdiction to obtain an advisory medical opinion under section 5109 of this title."],[0,"(3) Nothing in this subsection shall be construed to imply that the Secretary, during the consideration of a claim, does not have a duty to correct an error described in paragraph (1) or (2) that was erroneously not identified during higher-level review or during review on appeal with respect to the claim."],[0,"(g) Regulations.—The Secretary shall prescribe regulations to carry out this section."],[0,"(h) Rule With Respect to Disallowed Claims.—Nothing in this section shall be construed to require the Secretary to readjudicate a claim that has been disallowed except when new and relevant evidence is presented or secured, as described in section 5108 of this title."],[0,"(i) Other Assistance Not Precluded.—Nothing in this section shall be construed as precluding the Secretary from providing such other assistance under subsection (a) to a claimant in substantiating a claim as the Secretary considers appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5103A?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5103A. Duty to assist claimants","tname":"Veterans' Benefits","by":{"1":"4"}},{"t":"usc","label":"38 U.S.C. § 7104","url":"https://www.law.cornell.edu/uscode/text/38/7104","subs":["(a)"],"by":{"1":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 52","url":"https://www.law.cornell.edu/rules/frcp/rule_52","subs":["(a)(6)"],"by":{"1":"24"}},{"t":"case","label":"Chiaverini v. City of Napoleon","cite":"144 S. Ct. 1745","y":2024,"id":"2023/23-50","sc":1,"sum":"Pursuant to the Fourth Amendment and traditional common-law practice, the presence of probable cause for one charge in a criminal proceeding does not categorically defeat a Fourth Amendment malicious-prosecution claim relating to another, baseless charge.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"24"}},{"t":"case","label":"Cohen v. Brown","cite":"10 Vet. App. 128","y":1997,"url":"https://www.courtlistener.com/c/Vet.%20App./10/128/","by":{"2":"15"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"op":3,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 15"}},{"t":"case","label":"Wade v. Derwinski","cite":"3 Vet. App. 70","y":1992,"url":"https://www.courtlistener.com/c/Vet.%20App./3/70/","sum":"Finding legal error when Board applied higher standard of proof than section 5107(b) requires.","sumSrc":"brief:2","by":{"2":"15"}},{"t":"case","label":"Wensch v. Principi","cite":"15 Vet. App. 362","y":2001,"url":"https://www.courtlistener.com/c/Vet.%20App./15/362/","op":1,"ar":1,"by":{"2":"16"}}]};